Configuration.parameter:
[
  {
    "name": "echo",
    "description": "Echoes back whatever text is sent, to verify the request/response round-trip.",
    "inputSchema": {
      "type": "object",
      "properties": { "text": { "type": "string" } },
      "required": ["text"]
    }
  },
  {
    "name": "server_time",
    "description": "Returns the VDI server's current time. Takes no arguments.",
    "inputSchema": { "type": "object", "properties": {} }
  }
]

Script.parameter:
var tool = work.getString("$mcp.tool");

var argsJson = work.getString("$mcp.arguments");
var args = com.ibm.json.java.JSONObject.parse(argsJson);

if (tool == "echo") {
    var text = args.get("text");
    work.setAttribute("$mcp.result", "echo: " + text);
} else if (tool == "server_time") {
    var now = new java.util.Date();
    work.setAttribute("$mcp.result", now.toString());
    var structured = new com.ibm.json.java.JSONObject();
    structured.put("epochMillis", now.getTime());
    structured.put("iso", now.toInstant().toString());
    work.setAttribute("$mcp.structured", structured.serialize());
} else {
    work.setAttribute("$mcp.isError", "true");
    work.setAttribute("$mcp.result", "Unknown tool: " + tool);
}

task.logmsg("Check work:")
task.dumpEntry(work)

Hook.Script:
if (work != null) {
  var uid = work.getString("userId");
  var base = system.getTDIProperty("ldapSearchBase_people");
  thisConnector.connector.setParam("ldapSearchFilter",
    "(&(objectClass=groupOfNames)(member=uid=" + uid + "," + base + "))");
}

function esc(s){ return String(s).replace(/\\/g,"\\5c").replace(/\*/g,"\\2a").replace(/\(/g,"\\28").replace(/\)/g,"\\29").replace(/\u0000/g,"\\00"); }
var q = esc(work.getString("q"));
thisConnector.connector.setParam("ldapSearchFilter", "(&(objectClass=inetOrgPerson)(|(cn=*"+q+"*)(sn=*"+q+"*)(uid=*"+q+"*)(mail=*"+q+"*)))");

if (work != null) {
  var uid = work.getString("userId");
  var base = system.getTDIProperty("ldapSearchBase_people");
  thisConnector.connector.setParam("ldapSearchFilter",
    "(&(objectClass=groupOfNames)(member=uid=" + uid + "," + base + "))");
}

Script.parameter:
var JSONObject = Packages.com.ibm.json.java.JSONObject;
var JSONArray  = Packages.com.ibm.json.java.JSONArray;
var Arr        = java.lang.reflect.Array;

// Attributes that must always serialize as an array, even with one value:
var listAttrs = { "groups": true, "member": true, "matches": true };

function skip(nm){
  return nm.indexOf("$mcp.")==0 || nm.indexOf("http.")==0 || nm.indexOf("conn.")==0 || nm=="userPassword";
}
function isList(nm, a){ return a.size() > 1 || listAttrs[nm] === true; }  // fix #2

var names = work.getAttributeNames();
var n = Arr.getLength(names);
var out = new JSONObject();
for (var i=0; i<n; i++){
  var nm = names[i];
  if (skip(nm)) continue;
  var a = work.getAttribute(nm);
  if (a == null) continue;
  if (isList(nm, a)){                              // fix #2: force array for lists
    var arr = new JSONArray();
    for (var j=0; j<a.size(); j++) arr.add(String(a.getValue(j)));
    out.put(nm, arr);
  } else {
    out.put(nm, String(a.getValue()));
  }
}
work.setAttribute("$mcp.structured", out.toString());

var cur = work.getString("$mcp.result");
if (cur == null || cur == ""){
  var text = "";
  for (var k=0; k<n; k++){
    var nm2 = names[k];
    if (skip(nm2)) continue;
    var a2 = work.getAttribute(nm2);
    var v = "";                                    // fix #1: join ALL values, not just first
    for (var m=0; m<a2.size(); m++){ if (v != "") v = v + " | "; v = v + a2.getValue(m); }
    if (text != "") text = text + "; ";
    text = text + nm2 + ": " + v;
  }
  work.setAttribute("$mcp.result", text);
}
